    dwellTimes: [],
    ddTimes: [],
    bigramTimings: {},
    fatigueWindows: [],
    lastKeyTime: 0,
    lastKeyChar: '',
    lastKeyDownTime: 0,
    keyDownTimes: {},
    perKeyDwells: {},
